select update_for_date, status, started_at, finished_at, round(extract(epoch from finished_at-started_at)/60.0,1) minutes, eligible_tickers, completed_tickers, failed_tickers from public."Monitoring_Feature04" where run_type='DAILY' and status='SUCCESS' order by update_for_date desc limit 14;;
select count(*), round(avg(extract(epoch from finished_at-started_at))::numeric,3) avg_s, round(max(extract(epoch from finished_at-started_at))::numeric,1) max_s, avg(source_rows), max(source_rows), min(source_rows) from public."Feature04_Calculation_Log" where started_at > now() - interval '7 days' and result='SUCCESS';;
select date_trunc('day', finished_at) d, max(finished_at) from public."Feature04_Calculation_Log" where started_at > now() - interval '3 days' group by 1 order by 1
